package com.markettwits.selfupdater.thirdparty.api

import android.util.Base64
import android.app.Activity
import android.content.ClipData
import android.content.Intent
import android.net.Uri
import android.provider.Settings
import androidx.core.content.FileProvider
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import kotlinx.coroutines.runBlocking
import org.junit.Assume.assumeTrue
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File
import java.security.MessageDigest
import kotlin.test.assertEquals
import kotlin.test.assertIs

class InstallerFixtureActivity : Activity()

/** Run with isolated APKs generated by tools/spikes/android-apk-upgrade/run.sh. */
@RunWith(AndroidJUnit4::class)
class SignedUpgradeFixtureDeviceTest {
    @Test
    fun verifiesRealSignedUpgradeAndRejectsWrongSignerAndDowngrade() = runBlocking {
        val args = InstrumentationRegistry.getArguments()
        assumeTrue("Signed fixtures were not supplied", args.containsKey("good_apk"))
        val testContext = InstrumentationRegistry.getInstrumentation().targetContext
        val fixtureContext = testContext.createPackageContext("com.markettwits.updater.fixture", 0)
        val verifier = AndroidApkVerifier(fixtureContext)
        suspend fun check(key: String, version: Long): ApkFileVerification {
            val bytes = Base64.decode(requireNotNull(args.getString(key)), Base64.DEFAULT)
            val file = File(testContext.cacheDir, "$key.apk")
            try {
                file.writeBytes(bytes)
                val digest = MessageDigest.getInstance("SHA-256").digest(bytes)
                    .joinToString("") { (it.toInt() and 255).toString(16).padStart(2, '0') }
                return verifier.verify(file, ApkDownloadExpectation(version, bytes.size.toLong(), digest))
            } finally { file.delete() }
        }
        assertEquals(ApkFileVerification.Verified, check("good_apk", 101))
        assertEquals(ApkVerificationFailure.SigningMismatch,
            assertIs<ApkFileVerification.Rejected>(check("wrong_signer_apk", 102)).reason)
        assertEquals(ApkVerificationFailure.NotAnUpgrade,
            assertIs<ApkFileVerification.Rejected>(check("old_apk", 99)).reason)
        if (args.getString("launch_installer") == "true") {
            val directory = File(testContext.filesDir, "self-updater").apply { mkdirs() }
            val file = File(directory, "fixture-update.apk")
            file.writeBytes(Base64.decode(requireNotNull(args.getString("good_apk")), Base64.DEFAULT))
            val uri = FileProvider.getUriForFile(testContext, "${testContext.packageName}.selfupdater.files", file)
            val intent = Intent(Intent.ACTION_VIEW).setDataAndType(uri, "application/vnd.android.package-archive")
                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_GRANT_READ_URI_PERMISSION)
                .also { it.clipData = ClipData.newRawUri("update", uri) }
            val instrumentation = InstrumentationRegistry.getInstrumentation()
            val activity = instrumentation.startActivitySync(Intent(testContext, InstallerFixtureActivity::class.java)
                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
            if (args.getString("permission_flow") == "true") {
                check(!testContext.packageManager.canRequestPackageInstalls()) { "Expected installation permission to be disabled" }
                instrumentation.runOnMainSync {
                    activity.startActivity(Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES, Uri.parse("package:${testContext.packageName}")))
                }
                var allowed = false
                for (attempt in 1..30) {
                    if (testContext.packageManager.canRequestPackageInstalls()) { allowed = true; break }
                    kotlinx.coroutines.delay(1_000)
                }
                check(allowed) { "Installation permission was not granted" }
                var returned = false
                for (attempt in 1..30) {
                    instrumentation.runOnMainSync { returned = activity.hasWindowFocus() }
                    if (returned) break
                    kotlinx.coroutines.delay(1_000)
                }
                check(returned) { "Did not return from installation settings" }
            }
            instrumentation.runOnMainSync { activity.startActivity(intent) }
            // Keep the invoking activity alive while the test driver confirms the system UI.
            repeat(30) {
                if (testContext.packageManager.getPackageInfo(fixtureContext.packageName, 0).buildNumber() >= 101) return@runBlocking
                kotlinx.coroutines.delay(1_000)
            }
            error("System installer did not finish")
        }
    }
}
